125	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
126	        // abbreviations) and store the normalized form back on the DTO so it is what gets
127	        // persisted and compared. Reject the create when the address is blank once normalized.
128	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
129	        if (canonicalAddress.isBlank()) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        ownerFieldsDto.setAddress(canonicalAddress);
133	        // Reject the create when the owner's city is already at capacity, i.e. it already
134	        // contains 50 or more owners (compared case-insensitively).
135	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
139	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
140	        if (normalizedTelephone == null) {
141	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
142	        }
143	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
144	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
145	            .map(Owner::getTelephone)
146	            .map(OwnerRestControllerV1::toE164)
147	            .filter(existing -> existing != null)
148	            .anyMatch(normalizedTelephone::equals);
149	        if (telephoneInUse) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        // Reject the create when another owner already shares this owner's last name and address
153	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
154	        // sharing a household.
155	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
156	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
157	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
158	            boolean householdInUse = this.clinicService.findAllOwners().stream()
159	                .anyMatch(existing ->
160	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
161	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
162	            if (householdInUse) {
163	                return new ResponseEntity<>(HttpStatus.CONFLICT);
164	            }
165	        }
166	        // Determine the effective registration date — the value supplied on the request, or the
167	        // server's current date when none was supplied — and roll it forward to the next business
168	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
169	        // registration date (membership-number year segment, per-day create-limit) uses this
170	        // adjusted date.
171	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
172	        if (registrationDate == null) {
173	            registrationDate = LocalDate.now();
174	        }
175	        registrationDate = toBusinessDay(registrationDate);
176	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
177	        // owners have already been registered on this (adjusted) business day.
178	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
179	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
180	        }
181	        ownerFieldsDto.setTelephone(normalizedTelephone);
182	        HttpHeaders headers = new HttpHeaders();
183	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
184	        owner.setRegistrationDate(registrationDate);
185	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
186	        // letters of the city, the upper-cased first three letters of the last name, and a
187	        // per-city 4-digit sequence one greater than the number of owners already in that city.
188	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
189	        // Record how many existing owners already share this owner's first and last name
190	        // (compared case-insensitively) at the moment before this owner is created.
191	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
192	        this.clinicService.saveOwner(owner);
193	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
194	        headers.setLocation(UriComponentsBuilder.newInstance()
195	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
196	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
197	    }
198	
199	    /**
200	     * Validate and normalize the optional owner email in place.
201	     *
202	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
203	     * When present it must be a syntactically valid address; a valid address is
204	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
205	     * present but syntactically invalid, so the caller can reject with 400.
206	     */
207	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
208	        String email = ownerFieldsDto.getEmail();
209	        if (email == null || email.isBlank()) {
210	            ownerFieldsDto.setEmail(null);
211	            return true;
212	        }
213	        String normalized = email.trim().toLowerCase(Locale.ROOT);
214	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
215	            return false;
216	        }
217	        ownerFieldsDto.setEmail(normalized);
218	        return true;
219	    }
220	
221	    /**
222	     * Normalize an owner address: trim, collapse each run of whitespace to a single
223	     * space, upper-case, and expand common street-type abbreviations
224	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
225	     * A {@code null} value normalizes to the empty string.
226	     */
227	    private static String normalizeAddress(String value) {
228	        if (value == null) {
229	            return "";
230	        }
231	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
232	        if (collapsed.isEmpty()) {
233	            return "";
234	        }
235	        String[] tokens = collapsed.split(" ");
236	        StringBuilder sb = new StringBuilder(collapsed.length());
237	        for (int i = 0; i < tokens.length; i++) {
238	            if (i > 0) {
239	                sb.append(' ');
240	            }
241	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
242	        }
243	        return sb.toString();
244	    }
245	
246	    /**
247	     * Normalize an owner household field (last name or address) for duplicate detection:
248	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
249	     * A {@code null} value normalizes to the empty string.
250	     */
251	    private static String normalizeHouseholdKey(String value) {
252	        if (value == null) {
253	            return "";
254	        }
255	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
256	    }
257	
258	    /**
259	     * Normalize a telephone number to E.164 form.
260	     *
261	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
262	     * explicit leading {@code '+'} and country code it is kept; otherwise the
263	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
264	     * dropped from the national digits. The result must contain 8 to 15 digits
265	     * after the {@code '+'}.
266	     *
267	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
268	     *         the input is absent or cannot form a valid E.164 number.
269	     */
270	    private static String toE164(String raw) {
271	        if (raw == null) {
272	            return null;
273	        }
274	        String trimmed = raw.trim();
275	        boolean hasCountryCode = trimmed.startsWith("+");
276	        // Strip spaces, dashes and brackets.
277	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
278	        String digits;
279	        if (hasCountryCode) {
280	            // Keep the explicit country code; drop the leading '+' for validation.
281	            digits = stripped.substring(1);
282	        } else {
283	            // No country code: assume '+61' and drop a single leading '0'.
284	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
285	            digits = "61" + national;
286	        }
287	        if (!digits.matches("\\d{8,15}")) {
288	            return null;
289	        }
290	        return "+" + digits;
291	    }
292	
293	    /**
294	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
295	     *
296	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
297	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
298	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
299	     * equal to one more than the number of owners already in that city
300	     * (e.g. {@code 'SYD-SMI-0007'}).
301	     */
302	    /**
303	     * Count the existing owners whose first and last name match the given names,
304	     * compared case-insensitively. Used to record an owner's namesake count at the
305	     * moment before it is created.
306	     */
307	    private int countNamesakes(String firstName, String lastName) {
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> existing.getFirstName() != null
310	                && existing.getFirstName().equalsIgnoreCase(firstName)
311	                && existing.getLastName() != null
312	                && existing.getLastName().equalsIgnoreCase(lastName))
313	            .count();
314	    }
315	
316	    private String nextCustomerCode(String city, String lastName) {
317	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
318	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
319	        int sequence = countOwnersInCity(city) + 1;
320	        return String.format("%s-%s-%04d", city3, last3, sequence);
321	    }
322	
323	    /**
324	     * Count the existing owners located in the given city, compared case-insensitively.
325	     * Used to derive the per-city 4-digit sequence in the customer code.
326	     */
327	    private int countOwnersInCity(String city) {
328	        return (int) this.clinicService.findAllOwners().stream()
329	            .filter(existing -> existing.getCity() != null
330	                && existing.getCity().equalsIgnoreCase(city))
331	            .count();
332	    }
333	
334	    /**
335	     * Count the existing owners whose registration date is the given (adjusted business) date.
336	     * Used to enforce the per-day sign-up limit.
337	     */
338	    private int countOwnersRegisteredOn(LocalDate date) {
339	        return (int) this.clinicService.findAllOwners().stream()
340	            .filter(existing -> date.equals(existing.getRegistrationDate()))
341	            .count();
342	    }
343	
344	    /**
345	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
346	     * the following Monday; a weekday is returned unchanged.
347	     */
348	    private static LocalDate toBusinessDay(LocalDate date) {
349	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
350	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
351	            date = date.plusDays(1);
352	        }
353	        return date;
354	    }
355	
356	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
357	    @Override
358	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
359	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
360	        if (currentOwner == null) {
361	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
362	        }
363	        if (!normalizeEmail(ownerFieldsDto)) {
364	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
365	        }
366	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
367	        if (normalizedTelephone == null) {
368	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
369	        }
370	        currentOwner.setAddress(ownerFieldsDto.getAddress());
371	        currentOwner.setCity(ownerFieldsDto.getCity());
372	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
373	        currentOwner.setLastName(ownerFieldsDto.getLastName());
374	        currentOwner.setTelephone(normalizedTelephone);
375	        currentOwner.setEmail(ownerFieldsDto.getEmail());
376	        this.clinicService.saveOwner(currentOwner);
377	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Transactional
382	    @Override
383	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
384	        Owner owner = this.clinicService.findOwnerById(ownerId);
385	        if (owner == null) {
386	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
387	        }
388	        this.clinicService.deleteOwner(owner);
389	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
390	    }
391	
392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        HttpHeaders headers = new HttpHeaders();
400	        Pet pet = petMapper.toPet(petFieldsDto);
401	        owner.setId(ownerId);
402	        pet.setOwner(owner);
403	        pet.getType().setName(null);
404	        this.clinicService.savePet(pet);
405	        PetDto petDto = petMapper.toPetDto(pet);
406	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
407	            .buildAndExpand(pet.getId()).toUri());
408	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
414	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
415	        if (currentOwner != null) {
416	            Pet currentPet = this.clinicService.findPetById(petId);
417	            if (currentPet != null) {
418	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
419	                currentPet.setName(petFieldsDto.getName());
420	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
421	                this.clinicService.savePet(currentPet);
422	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
423	            }
424	        }
425	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
431	        HttpHeaders headers = new HttpHeaders();
432	        Visit visit = visitMapper.toVisit(visitFieldsDto);
433	        Pet pet = new Pet();
434	        pet.setId(petId);
435	        visit.setPet(pet);
436	        this.clinicService.saveVisit(visit);
437	        VisitDto visitDto = visitMapper.toVisitDto(visit);
438	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
439	            .buildAndExpand(visit.getId()).toUri());
440	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
441	    }
442	
443	
444	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
445	    @Override
446	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
447	        Owner owner = this.clinicService.findOwnerById(ownerId);
448	        if (owner != null) {
449	            Pet pet = owner.getPet(petId);
450	            if (pet != null) {
451	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
452	            }
453	        }
454	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	    }
